SET NAMES utf8mb4;

DROP TABLE IF EXISTS `community_parking_space`;
CREATE TABLE `community_parking_space` (
  `space_id` bigint NOT NULL COMMENT '车位ID',
  `community_id` bigint DEFAULT NULL COMMENT '小区ID',
  `space_no` varchar(64) DEFAULT NULL COMMENT '车位编号',
  `space_area` varchar(100) DEFAULT NULL COMMENT '车位区域',
  `space_type` varchar(32) DEFAULT NULL COMMENT '车位类型（地上 地下 临时）',
  `use_status` char(1) DEFAULT '0' COMMENT '使用状态（0空闲 1已使用 2停用）',
  `owner_id` bigint DEFAULT NULL COMMENT '绑定业主ID',
  `vehicle_id` bigint DEFAULT NULL COMMENT '绑定车辆ID',
  `start_date` date DEFAULT NULL COMMENT '开始日期',
  `end_date` date DEFAULT NULL COMMENT '结束日期',
  `monthly_fee` decimal(10,2) DEFAULT NULL COMMENT '月租费用',
  `create_by` varchar(32) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(32) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(1024) DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`space_id`),
  KEY `idx_parking_space_community_id` (`community_id`),
  KEY `idx_parking_space_owner_id` (`owner_id`),
  KEY `idx_parking_space_vehicle_id` (`vehicle_id`),
  KEY `idx_parking_space_no` (`space_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='停车位表';

DROP TEMPORARY TABLE IF EXISTS `tmp_parking_ref`;
CREATE TEMPORARY TABLE `tmp_parking_ref` AS
SELECT (@rownum := @rownum + 1) AS rn, t.*
FROM (
  SELECT v.vehicle_id, v.owner_id, od.community_id
  FROM `community_vehicle` v
  INNER JOIN `owner_room` od ON od.owner_id = v.owner_id AND od.room_id = v.room_id
  ORDER BY v.vehicle_id
  LIMIT 4
) t, (SELECT @rownum := 0) x;

